package app.vidloader;
import java.util.*;import org.json.*;import java.io.*;
final class DesktopSites{
 static List<MediaCandidate> extract(String page,String title,String ua,JSONObject captured)throws Exception{
 List<MediaCandidate> out=new ArrayList<>();Map<String,String> headers=new LinkedHashMap<>();headers.put("Referer",page);headers.put("User-Agent",ua);
 if(BilibiliPlayback.isFeaturePage(page)){String request=BilibiliPlayback.initialRequest(page);if(request.equals(page))request=BilibiliPlayback.episodeFallback(page,HttpMedia.text(page,headers,2*1024*1024));if(!request.isEmpty()){JSONObject payload=new JSONObject(HttpMedia.text(request,headers,2*1024*1024));BilibiliPlayback.Result result=BilibiliPlayback.parse(payload.toMap());for(BilibiliPlayback.Track t:result.videos){MediaCandidate c=new MediaCandidate(t.url,title,"video/mp4",t.width,t.height,"Original Bilibili playurl",MediaCandidate.Kind.DIRECT,0,"","",result.audioFor(t),false,"",Collections.emptyList(),"",Collections.emptyList(),"");c.qualityHint=t.heightHint;c.durationMs=result.durationValue;c.referer=page;c.origin=DesktopBridge.origin(page);c.userAgent=ua;out.add(c);}}}
 if(Fc2Playback.isContentPage(page)&&captured!=null){Fc2Playback.Session session=new Fc2Playback.Session(page);Iterator<String> urls=captured.keys();while(urls.hasNext()){String url=urls.next();JSONObject h=captured.optJSONObject(url);if(h==null)continue;Map<String,String> map=new LinkedHashMap<>();Iterator<String> keys=h.keys();while(keys.hasNext()){String k=keys.next();map.put(k,h.optString(k));}session.observe(url,map);}if(session.hasToken()){JSONObject playlist=new JSONObject(HttpMedia.text(session.playlist,session.headersFor(session.playlist,headers),1024*1024)).optJSONObject("playlist");if(playlist!=null){Map<String,String> values=new LinkedHashMap<>();for(String k:new String[]{"nq","sample","hq","lq"})if(playlist.opt(k) instanceof String)values.put(k,playlist.optString(k));boolean primary=false;for(Fc2Playback.Choice ch:Fc2Playback.playlistChoices(page,values)){MediaCandidate c=new MediaCandidate(ch.url,title,"video/mp4",0,ch.originalHeight,"Original FC2 playlist");c.qualityHint=true;c.referer=page;c.origin=DesktopBridge.origin(page);c.userAgent=ua;if(ch.primary){c=MediaResponseProbe.inspect(c,headers,true);primary=c!=null&&c.mime.startsWith("video/");}if(!primary)break;out.add(c);}}}}
 return out;}
 static String vk(JSONObject d)throws Exception{VkApiRequest.Request r=VkApiRequest.validate(d.optString("page"),d.optString("planPage"),d.optString("id"),d.optString("url"),d.optString("body"));if(r==null)throw new IOException("Rejected stale or invalid VK request");Map<String,String> h=new LinkedHashMap<>();h.put("Referer",d.optString("page"));h.put("Origin",DesktopBridge.origin(d.optString("page")));h.put("User-Agent",d.optString("userAgent"));return HttpMedia.postForm(r.url,r.body,h,1024*1024);}
}